let name = env.get("Name");
let language = config.language;
let info = global.get('translate');
if(info.dash === undefined) {
    return
}
if (info.dash[name] === undefined) {
    if(info.dash[name[0].toUpperCase() + name.slice(1)] !== undefined) {
        info.dash[name] = info.dash[name[0].toUpperCase() + name.slice(1)]
    }
}
if (info.dash[name] !== undefined) {
    if (info.dash[name][language] !== undefined) {
        info = info.dash[name][language]
    }
}
msg.label = info;
return msg;

let config_msg = global.get('config');
let path = env.get("Path")
// If we don't have a config message, we can't update it, this might be due to the new version not having the config message yet, returning is fine as the new config is saved in the new way
if (config_msg === undefined) {
    global.set('config', msg.config)
    return msg;
}
let out = {}; // This is for the output message, we don't want the entire config message to be sent out.
let cfg = config_msg.config; // For compatibility with old configs, this should be removed later after a while.
let cfg2 = config_msg.payload;
let config = cfg2 || cfg;
if (path !== '') {
    let path_split = path.split(".");
    let path_cfg = config;
    // Last index
    let i;
    for (i = 0; i < path_split.length - 1; i++) {
        if (path_cfg[path_split[i]] === undefined) {
            path_cfg[path_split[i]] = {};
        }
        path_cfg = path_cfg[path_split[i]];
    }
    path_cfg[path_split[i]] = msg.config;
    path_cfg = out;
    for (i = 0; i < path_split.length - 1; i++) {
        if (path_cfg[path_split[i]] === undefined) {
            path_cfg[path_split[i]] = {};
        }
        path_cfg = path_cfg[path_split[i]];
    }
    path_cfg[path_split[i]] = msg.config;
}
else {
    config = msg.config;
    out = msg.config;
}
if (cfg2) {
    config_msg.payload = config;
}
else if (cfg) {
    config_msg.config = config;
}
global.set('config', config_msg);
msg.payload = out;
return msg;

