// Förväntar sig payload[0] med serier där en serie = cpr_act (0/1)
// Bygger två serier per timbucket: duty (%) och starter/h
if (!Array.isArray(msg.payload) || !msg.payload[0]) return null;
const pkg = msg.payload[0];
const series = pkg.series || [];
const data = pkg.data || [];
// Hitta index för cpr_act
let idx = series.findIndex(s => /cpr[_ ]?act|compressor/i.test(String(s)));
if (idx === -1) idx = 0; // fallback första serien
const rows = data[idx] || [];
// rows: [[ts,value], ...] där value ~ 0/1
// Bucket per timme
const buckets = new Map();
for (const [ts, v] of rows) {
  const t = new Date(ts);
  const key = new Date(t.getFullYear(), t.getMonth(), t.getDate(), t.getHours()).getTime();
  if (!buckets.has(key)) buckets.set(key, {onMs:0, totalMs:0, lastTs:null, lastV:null, starts:0});
  const b = buckets.get(key);
  if (b.lastTs!==null) {
    const dt = Math.max(0, ts - b.lastTs);
    b.totalMs += dt;
    if (b.lastV>=1) b.onMs += dt;
    if (b.lastV<1 && v>=1) b.starts += 1; // stigande flank = start
  }
  b.lastTs = ts; b.lastV = v;
}
// Till serier för ui_chart
const dutySeries = [], startSeries = [];
[...buckets.keys()].sort().forEach(k => {
  const b = buckets.get(k);
  const duty = b.totalMs>0 ? (b.onMs/b.totalMs)*100 : 0;
  dutySeries.push([k, Number(duty.toFixed(1))]);
  startSeries.push([k, b.starts]);
});
const out = [{series:["Duty %","Starter/h"], data:[dutySeries,startSeries]}];
msg.payload = out;
return msg;

