if (source === true) {
    msg = {
        enabled: true
    };
    return msg;
} else {
    msg = {
        enabled: false
    };
    return msg;
}

// Ta bara hand om VV-AI-grafen
if (msg.topic !== "nibe_vv_ai" && msg.topic !== "update") {
        return null;
}

// Tillåt "clear chart" (msg.payload = []) att passera igenom
if (Array.isArray(msg.payload) && msg.payload.length === 0) {
        return msg; // ui_chart tolkar [] som "clear"
}

var payload = msg.payload || {};
if (!payload.values || !Array.isArray(payload.values) || !payload.values[0]) {
        return null;
}

var g = payload.values[0];
var series = Array.isArray(g.series) ? g.series : [];
var data = Array.isArray(g.data) ? g.data : [];

// Vi vill alltid jobba med en vecka = 168 timmar
var pointCount = 167;

// Om första serien är kortare (t.ex. precis efter start) – anpassa nedåt
if (!data[0] || !Array.isArray(data[0]) || data[0].length === 0) {
        return null; // inget att rita
}
if (data[0].length < pointCount) {
        pointCount = data[0].length;
}

// Bygg en "vecka" med 1 timmes steg, start måndag 00:00
var base = new Date();
base.setHours(0, 0, 0, 0);         // idag kl 00:00
var day = base.getDay();           // 0 = sön, 1 = mån, ... 6 = lör
var diffToMonday = (day + 6) % 7;  // hur många dagar bakåt till måndag
base.setDate(base.getDate() - diffToMonday);
var baseMs = base.getTime();       // måndag 00:00 i ms

// Konvertera [{x,y} ..] eller [y,..] -> [{x:timestamp,y},..] per serie
var dataXY = data.map(function (serieArr) {
        if (!Array.isArray(serieArr)) return [];

        var out = [];
        for (var i = 0; i < pointCount; i++) {
                var p = serieArr[i];
                var y;

                if (p && typeof p.y === "number") {
                        y = p.y;
                } else if (typeof p === "number") {
                        y = p;
                } else {
                        y = 0;
                }

                var x = baseMs + i * 3600000; // 1 timme = 3 600 000 ms
                out.push({ x: x, y: y });
        }
        return out;
});

// --- Flytta serie till FRONT (så den ritas överst i din ui_chart) ---
function moveNameToFront(nameExact) {
        var idx = series.indexOf(nameExact);
        if (idx >= 0) {
                var sMoved = series.splice(idx, 1)[0];
                var dMoved = dataXY.splice(idx, 1)[0];
                series.unshift(sMoved);
                dataXY.unshift(dMoved);
        }
}

// Vill du ha grön överst: flytta röd först, sen grön (grön hamnar index 0)
moveNameToFront("VV-pris blockerat (röd)");
moveNameToFront("VV-pris värmefönster (grön)");

// Skicka timeseries-paket till ui_chart
msg.payload = [{
        series: series,
        data: dataXY,
        labels: [""]   // krävs men används inte vid tidsaxel
}];

// Styr x-axelns format: dag + klockslag
var weekMs = 7 * 24 * 3600000;   // 7 dygn i ms

msg.ui_control = msg.ui_control || {};
msg.ui_control.xformat = "ddd HH:mm";
msg.ui_control.xmin = new Date(baseMs).toISOString();
msg.ui_control.xmax = new Date(baseMs + weekMs - 1).toISOString();

return msg;
